import {apps,books,demoBooks,topics,difficulties} from './data.js';
import {recommend,validateBooks,safeSource} from './recommend.js';
const main=document.querySelector('main');
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView();});
let choice={topic:'',difficulty:''};
const isDemo=()=>location.hash==='#demo';
function el(tag,attrs={},children=[]){const node=document.createElement(tag);for(const [key,value] of Object.entries(attrs)){if(key==='class')node.className=value;else if(key==='text')node.textContent=value;else node.setAttribute(key,value);}for(const child of children)if(child)node.append(child);return node;}
const text=(tag,value,cls)=>el(tag,{text:value,...(cls?{class:cls}:{})});
const button=(label,handler,secondary=false)=>{const b=el('button',{class:`button${secondary?' secondary':''}`,type:'button',text:label});b.addEventListener('click',handler);return b;};
const link=(label,href,cls='button')=>el('a',{text:label,href,class:cls});
function focusTitle(){main.querySelector('h1,h2')?.focus();}
function art(){return el('div',{class:'art','aria-hidden':'true'},[el('div',{class:'ribbon'}),el('div',{class:'book-art'},[text('span','✳')]),text('div','✦','sticker star'),text('div','♡','sticker heart'),text('div','HELLO, BOOK!','sticker hello')]);}
function hub(){main.replaceChildren();const content=el('div',{class:'wrap hero-inner'},[el('div',{},[text('div','LEARN · EXPLORE · GROW','eyebrow'),el('h1',{tabindex:'-1',class:'focus-heading'},[document.createTextNode('호기심을 모아,'),el('br'),text('em','배움을 펼쳐요.')]),text('p','책을 만나고, 새로운 생각을 발견하고. 나의 배움에 꼭 맞는 프로그램을 한곳에서 만나보세요.'),link('배움 시작하기 ↗','#programs')]),art()]);main.append(el('section',{class:'hero'},[content]),el('div',{class:'ticker','aria-hidden':'true'},[text('span','✳ 작은 호기심, 커다란 발견'),text('span','✦ 책에서 시작하는 나의 세계'),text('span','✳ 함께 자라는 배움') ]));const grid=el('div',{class:'cards'});for(const app of apps){const ready=app.status==='ready'&&(/^#[a-z][a-z0-9-]*$/.test(app.route)||['./pdf-counter/'].includes(app.route));grid.append(el('article',{class:`app-card${ready?'':' pending'}`},[el('div',{},[text('span',app.category,'tag'),text('h3',app.name),text('p',app.description),ready?link(app.action||'책 친구 찾으러 가기 ↗',app.route):text('span','곧 만나요','pill')]),text('div',ready?'✳':'✦',ready?'mini-book':'mini-star')]));}main.append(el('section',{class:'wrap section',id:'programs'},[el('div',{class:'section-heading'},[text('h2','우리의 배움 도구'),text('span',`${apps.filter(a=>a.status==='ready').length}개의 프로그램 · 더 많은 배움이 준비 중`,'muted')]),grid,el('div',{class:'note-strip'},[text('span','이 공간은 앞으로 새로운 교육 프로그램으로 채워져요.'),link('추천 흐름 데모 보기 ↗','#demo','pill')])]));}
function header(demo){return el('section',{class:'app-header'},[el('div',{class:'wrap'},[link('← 프로그램으로','#hub','breadcrumb'),el('div',{class:'badge-line'},[text('span','독서 프로그램','tag'),text('span','5학년 프로토타입','tag'),...(demo?[text('span','합성 데이터 데모','tag')]:[])]),el('h1',{text:'오늘은 어떤 책을 만나볼까요?',tabindex:'-1',class:'focus-heading'}),text('p','좋아하는 주제와 읽고 싶은 난이도를 골라 주세요. 등록된 도서 목록과 선택 조건으로 책을 추천해요.')])]);}
function demoBanner(){return text('div','데모 화면이에요. 아래 책은 기능 확인용 가상 도서이며 실제 추천도서가 아닙니다.','demo-banner');}
function group(name,title,hint,items,levels=false){const field=el('fieldset');field.append(text('legend',title),text('p',hint,'hint'));const options=el('div',{class:`options${levels?' level':''}`});for(const item of items){const input=el('input',{type:'radio',name,value:item.id,'aria-describedby':`${name}-error`});input.checked=choice[name]===item.id;input.addEventListener('change',()=>{choice[name]=item.id;document.getElementById(`${name}-error`).textContent='';});const content=el('span',{class:'option-content'},levels?[el('span',{class:'option-text'},[document.createTextNode(item.name),text('small',item.description)])]:[text('span',item.icon,`option-icon ${item.color}`),text('span',item.name,'option-text')]);options.append(el('label',{class:'option'},[input,content]));}field.append(options,el('p',{id:`${name}-error`,class:'error','aria-live':'polite'}));return field;}
function select(){const demo=isDemo();main.replaceChildren(header(demo));const section=el('section',{class:'wrap section'});if(demo)section.append(demoBanner());section.append(el('div',{class:'steps','aria-label':'추천 순서'},[text('span','① 취향 고르기'),text('span','→'),text('span','② 책 만나기')]));const form=el('form',{novalidate:''});form.append(group('topic','1. 어떤 이야기가 궁금한가요?','마음이 가는 주제를 하나 골라 주세요.',topics),group('difficulty','2. 오늘은 어떻게 읽고 싶나요?','잘하고 못하는 기준이 아니라, 오늘의 읽기 취향이에요.',difficulties,true));const submit=el('button',{class:'button',type:'submit',text:'나의 책 친구 찾기 ↗'});form.append(el('div',{class:'actions'},[submit,link('허브로 돌아가기','#hub','button secondary')]),text('p','이름이나 학번을 입력하지 않아요. 선택과 추천 기록은 저장하지 않아요.','privacy-note'));form.addEventListener('submit',event=>{event.preventDefault();for(const name of ['topic','difficulty'])document.getElementById(`${name}-error`).textContent=choice[name]?'':`${name==='topic'?'관심 주제':'읽기 난이도'}를 하나 선택해 주세요.`;const missing=['topic','difficulty'].find(name=>!choice[name]);if(missing){form.querySelector(`input[name="${missing}"]`).focus();return;}results(demo);});section.append(form);if(!demo){const details=el('details',{class:'details'},[text('summary','도서 목록은 어떻게 준비하나요?'),text('p','학교 공개 권장도서 목록을 후보로 사용합니다. 주제·난이도·판본을 교사가 검토한 책만 실제 추천에 포함합니다. 전국 공통 필독 목록은 아닙니다.'),text('p',`현재 후보 ${books.length}권 · 승인 ${validateBooks(books).valid.filter(b=>b.reviewStatus==='approved').length}권`),link('기능 확인용 데모 열기','#demo','pill')]);section.append(details);}main.append(section);}
function results(demo){const result=recommend(demo?demoBooks:books,{...choice,grade:5});const topic=topics.find(t=>t.id===choice.topic),level=difficulties.find(d=>d.id===choice.difficulty);main.replaceChildren(header(demo));const section=el('section',{class:'wrap section'});if(demo)section.append(demoBanner());const heading=el('h2',{class:'result-title focus-heading',tabindex:'-1',text:result.books.length?'이 책 친구들을 만나보세요!':'다음 책 친구를 준비하고 있어요.'});section.append(heading,text('p',`5학년 · ${topic.name} · ${level.name}`,'summary'),el('p',{'aria-live':'polite',class:'muted',text:`조건에 맞는 책 ${result.books.length}권` }));if(result.books.length){const cards=el('div',{class:'results'});for(const [index,book] of result.books.entries()){const source=safeSource(book.sourceUrl);const sourceNode=source?el('a',{href:source,target:'_blank',rel:'noopener noreferrer',class:'source',text:book.sourceLabel}):text('p',book.sourceLabel,'source');cards.append(el('article',{class:'book-card'},[text('div','✳',`cover ${['lavender','yellow','mint'][index]}`),text('span',demo?'가상 도서 · 데모':'교사 검토 도서','tag'),text('h3',book.title),text('p',`${book.author} · ${book.publisher}`,'book-meta'),text('p',`${topic.name} 주제를 골랐고, ${level.name}를 원했어요. 이 책은 두 조건에 맞게 등록되어 있어요.`,'reason'),sourceNode]));}section.append(cards);}else{const approved=validateBooks(books).valid.some(b=>b.reviewStatus==='approved'&&b.grades.includes(5));section.append(el('div',{class:'empty'},[text('div','♧','empty-icon'),text('h3',approved?'조건에 맞는 책이 아직 없어요.':'선생님이 추천할 책을 살펴보고 있어요.'),text('p',approved?'다른 주제나 난이도로 다시 골라 보세요. 선택 조건과 다른 책을 대신 추천하지 않아요.':'후보 도서의 주제와 난이도를 검토한 뒤 책을 만나볼 수 있어요. 지금은 데모에서 추천 흐름을 확인할 수 있어요.'),...(!approved?[link('가상 도서로 데모 체험','#demo','button secondary')]:[])]));}section.append(el('div',{class:'actions'},[button('다시 골라 보기',()=>{select();focusTitle();}),link('허브로 돌아가기','#hub','button secondary')]));main.append(section);heading.focus();window.scrollTo(0,0);}
function route(){const hash=location.hash;if(hash==='#librarian'||hash==='#demo')select();else if(hash==='#hub'||hash===''||hash==='#programs')hub();else{main.replaceChildren(el('section',{class:'wrap section'},[el('h1',{text:'이 페이지를 찾을 수 없어요.',tabindex:'-1'}),link('프로그램으로 돌아가기','#hub')]));}document.title=isDemo()?'추천 데모 · 책별':hash==='#librarian'?'나의 책 친구 · 책별':'책별 · 배움의 허브';if(hash==='#programs')document.getElementById('programs')?.scrollIntoView();else window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{route();focusTitle();});route();

